\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 [TE]. - II + 2 IV\plain \f0\super\fs28 16\plain \f0\fs22  + V\plain \f0\super\fs28 26\plain \f0\fs22  + IV\plain \f0\super\fs28 34 \plain \f0\fs22 + III\plain \f0\super\fs28 40 \plain \f0\fs22 + 2 IV\plain \f0\super\fs28 56 \plain \f0\fs22 + (III+1)\plain \f0\super\fs28 63 \plain \f0\fs22 + 3 IV\plain \f0\super\fs28 87 \plain \f0\fs22 + (I+3)\plain \f0\super\fs28 92 \plain \f0\fs22 + 4 IV\plain \f0\super\fs28 124 \plain \f0\fs22 + (III+1)\plain \f0\super\fs28 131 \plain \f0\fs22 + 3\plain \f0\super\fs28 134 \plain \f0\fs22 \u8729 \'b7 Beschreibung der getilgten Hs (Fragmente aus drei Hss) s.u. \u183 \'b7 Reskribierte Hs: Schriftraum 20 \u215 \'d7 13,5 \u8729 \'b7 28 Z. \u8729 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Hybrida}}\plain \f0\fs22 , eine Hand (Valerius von Mayen) \u8729 \'b7 Rote, vereinzelt (49\plain \f0\super\fs28 rv\plain \f0\fs22 ) auch rot-blaue Rubrizierung (Valerius von Mayen) \u8729 \'b7 Zwei rot-schwarze bzw. rot-blaue {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Initialen mit Aussparungen und Knospenfleuronn\u233 \'e9e}}\plain \f0\fs22  (25\plain \f0\super\fs28 v\plain \f0\fs22 . 93\plain \f0\super\fs28 r\plain \f0\fs22 ; Werkstatt \u8222 \'84Maria Laach\ldblquote , um 1515, vgl. Bonn, ULB, S 357-359; Berlin, SB, Ms. lat. fol. 189); teilweise nicht ausgef\u252 \'fchrt \u8729 \'b7 I\plain \f0\super\fs28 r\plain \f0\fs22  Schreiber- und Besitzvermerk: \plain \f0\i\fs22 >Liber monasterii beate Marie virginis in Lacu, quem scripsit frater Valerius Meyensis adiuvante fratre Gregorio Euphaliano. Memor sit Deus utriusque<\plain \f0\fs22 , Valerius von Mayen, 1512/1516; danach Inhaltsverzeichnis: \plain \f0\i\fs22 >Variorum carminum libri tres charissimo fratri Johanni Butzbagio Piemontario preceptori suo dignissimo per fratrem Jacobum Siberti de monasterio Euphalie cenobitam Lacensem discipulum suum nuncupatum<\plain \f0\fs22 , Valerius von Mayen, 1512/1516}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

