\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 255\plain \f0\super\fs28 ra\plain \f0\fs22 -258\plain \f0\super\fs28 va\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Henricus de Langenstein}}\plain \f0\scaps\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Epistula de oblato episcopatu [Osiliensi] tempore scismatis ad Eckardum episcopum Wormatiensem}}\plain \f0\fs22 . Titel: \plain \f0\i\fs22 >Epistola Henrici de Hassia ad episcopum Wormatiensem utrum debeat assumere episcopatum sibi oblatum per papam tempore magni scismatis<.\plain \f0\fs22  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Reverendo in Christo patri ac domino domino Echardo }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (!)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17  Dei gracia episcopo Wormaciensi ... Henricus de Langenstein ... Venerande paternitatis vestre provida in dubiis discrecione}}\plain \f0\i\fs22  ... - ... e taliis, que circumspectior peritorum industria invenire scit m[ic]hi [pro]mulgand[am]. >Explicit auspicium, que poscit epistola divum in dubio sancto querens de tramite recto<.\plain \f0\fs22  Ed.: Hermann von der Hardt (Hg.): Inedita epistola Henrici de Hassia ... ad Eccardum de Dersch .. de oblato episcopatu Osiliensi in Livonia. Helmstedt 1715. Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Hohmann, Heinrich von Langenstein, 1976}}\plain \f0\fs22 , Nr. 202 (Lit.); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lang, Christologie, 1966}}\plain \f0\fs22 , S. 48. Am Rand vereinzelt Glossen von Schreiberhand. 258\plain \f0\super\fs28 vb\plain \f0\fs22  leer.}

