\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 [VE]. - {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Hybrida}}\plain \f0\fs22  und {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kursive}}\plain \f0\fs22 , vier H\u228 \'e4nde (Hinricus Isernloen, Arnoldus de Telget u.a.) \plain \f1\fs22 \u183 \'b7\plain \f0\fs22  Rubrizierung; {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lom\-barden mit Aussparungen, vereinzelt auch mit Knospenfleuronn\u233 \'e9e}}\plain \f0\fs22  \plain \f1\fs22 \u183 \'b7\plain \f0\fs22  Eine hellgr\u252 \'fcne historisierte {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lombardinitiale}}\plain \f0\fs22  (1\plain \f0\super\fs28 r\plain \f0\fs22  [Adam und Eva]; Entwurf) \u183 \'b7 1\plain \f0\super\fs28 r\plain \f0\fs22  Besitzvermerk: \plain \f0\i\fs22 >Liber domus sanctorum Petri principis apostolorum et Anthonii almi confessoris patronorum in Dalhem Paderburnensis dyocesis prope campum Sentfelt ordinis canonicorum regularium beatissimi patris Augustini episcopi Yponensis et doctoris principalis orthodoxe ecclesie etc.<\plain \f0\fs22 , um 1500\plain \f0\i\fs22  \plain \f1\fs22 \u183 \'b7\plain \f0\fs22  Vor Bl 140 sechs sowie nach Bl 168 vier Bll verloren (Textverlust). Nachsatz I-II urspr\u252 \'fcnglich Spiegel VD/RD.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

