\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 178\plain \f0\super\fs28 r\plain \f0\fs22 -181\plain \f0\super\fs28 r\plain \f0\fs22  \plain \f0\scaps\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Heinrich Kalteisen}}\plain \f0\scaps\fs22 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Consilium de introitu cuiusdam iuvenis in ordinem praedicatorum}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Contigit casus, quod quidam iuvenis intravit ordinem fratrum predicatorum existens etatis 13 annorum}}\plain \f0\i\fs22  ... - ... in ordine remanere, quod et fecit.\plain \f0\fs22  Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 VL (2)}}\plain \f0\fs22 , Bd. 4, Sp. 975 (Nr. 35c; Hs genannt); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kaeppeli, ScriptOP, 1970}}\plain \f0\fs22 , Nr. 1806c (Hs genannt). Am Rand vereinzelt Glossen von Kalteisen.}

