\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 236\plain \f0\super\fs28 vb\plain \f0\fs22 -237\plain \f0\super\fs28 ra\plain \f0\fs22  \plain \f0\scaps\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Henricus Kalteisen}}\plain \f0\scaps\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Sermo] in festo sanctae trinitatis}}\plain \f0\fs22 . Fragmentarische Entwurfsfassung (nur Prothema). \plain \f0\i\fs22 In festo Trinitatis beatissime. \plain \f0\i\fs22\chcbpat17 Tres unum {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (gestrichen und expungiert)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17  sunt ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (I Io 5,8)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 . In epistola de hodierne sollempnitatis eulogio venerabilis Albertanus}}\plain \f0\i\fs22  ... - ... eam solenter imploremus salutacione angelica dicentes >Ave Maria<.\plain \f0\fs22  Zu Werk und \u220 \'dcberlieferung vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Schneyer, Repertorium 2, 1990-1994}}\plain \f0\fs22 , s.v. 'Henricus Kalteisen', Nr. 2 (am Anfang Abweichungen; Hs genannt); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Pr\u252 \'fcgl, Ekklesiologie, 1995}}\plain \f0\fs22 , S. 41-44 (dat. Basel, 15. Juni 1432); 111 (Nr. 31; Hs genannt); {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 VL (2)}}\plain \f0\fs22 , Bd. 4, Sp. 972 (Nr. 7; Hs genannt); {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kaeppeli, ScriptOP, 1970}}\plain \f0\fs22 , Nr. 1780 (Hs genannt).}

