\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 315\plain \f0\super\fs28 r\plain \f0\fs22 -322\plain \f0\super\fs28 r\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Johannes Curvello}}\plain \f0\scaps\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Silvula carminum}}\plain \f0\fs22 . Mit Widmung von Curvello an Butzbach (Titel). (315\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Adhoratio ad rosarium}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Omnes nunc roseo curas immergite Christi}}\plain \f0\i\fs22  ...\plain \f0\fs22  (315\plain \f0\super\fs28 r\plain \f0\fs22 -317\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Carmen eucharisticon hecatostichon de passione domini nostri}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Christe sator secli Gabriele ex ethere misso}}\plain \f0\i\fs22  ...\plain \f0\fs22  (317\plain \f0\super\fs28 rv\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Carmen sapphicum de Sancto Benedicto}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Gaudeat felix nimium vetuste}}\plain \f0\i\fs22  ...\plain \f0\fs22  (317\plain \f0\super\fs28 v\plain \f0\fs22 -318\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Hecasticon de Sancto Benedicto}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Astriferis tetrica monachum tuum latus Olimpis}}\plain \f0\i\fs22  ...\plain \f0\fs22  (318\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Decastichon ad imaginem crucifixi}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Ut Phlegethotineo possis tutare palude}}\plain \f0\i\fs22  ...\plain \f0\fs22  (318\plain \f0\super\fs28 r\plain \f0\fs22 -321\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Carmen sapphicum de liliis vitae dominae virginis Mariae}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Nobilis Jesu genitrix aveto}}\plain \f0\i\fs22  ...\plain \f0\fs22  (321\plain \f0\super\fs28 r\plain \f0\fs22 -322\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Elegia de falso amico et de miseria praesentis vitae}}\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Quisquis es in mundo cernens quodcumque caducum}}\plain \f0\i\fs22  ...\plain \f0\fs22  Geschrieben von einer weiteren Hand. Zu Verfasser und Werken vgl. Friedrich Wilhelm Emil Roth: Johannes Curvello O.S.B. Ein ver\-ges\-se\-ner Humanist des XVI. Jahrhunderts. In: Annalen des historischen Vereins f\u252 \'fcr den Niederrhein 62 (1896), S. 209f. 322\plain \f0\super\fs28 v\plain \f0\fs22  Nachtrag: Lobgedicht auf Maria Laach mit Skizze des Klosterbaus, 18. Jh.}

