\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Resmini, Laach, 1993}}\plain \f0\fs22 , S. 73f. (Nr. 49). - {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Handschriftenzensus Rheinland}}\plain \f0\fs22 , Nr. 174. - {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kr\u228 \'e4mer, Handschriftenerbe, 1989-1990}}\plain \f0\fs22 , Bd. 1, S. 556. - {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kristeller, Iter, 1963-1993}}\plain \f0\fs22 , Bd. 3, S. 504. - Becker, S. [246-248]. - {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Rheinische Handschriften Bonn}}\plain \f0\fs22 , S. 26. - {\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Nick, Manuscripte Bonner UB, 1890}}\plain \f0\fs22 , S. 65 (Nr. 14). - {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Klette/St\u228 \'e4nder}}\plain \f0\fs22 , Nr. 358.}

