\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 [TE]. - (IV+1)\plain \f0\super\fs28 9\plain \f0\fs22  + 22 IV\plain \f0\super\fs28 185\plain \f0\fs22  + (IV+1)\plain \f0\super\fs28 194\plain \f0\fs22  \u183 \'b7 Beschreibung der getilgten Hs (Fragmente aus neun Hss) s.u. \u183 \'b7 Reskribierte Hs: Schriftraum 18,5 \u215 \'d7 12,5 \u183 \'b7 29-32 Z. \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Gotische Hybrida}}\plain \f0\fs22 , eine Hand \u183 \'b7 Rote und blaue Rubrizierung; {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lombarden teilweise mit Knospenfleuronn\u233 \'e9e}}\plain \f0\fs22  \u183 \'b7 21 blaue bzw. rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Initialen mit Knospenfleuronn\u233 \'e9e}}\plain \f0\fs22  (2\plain \f0\super\fs28 r\plain \f0\fs22 .  2\plain \f0\super\fs28 v\plain \f0\fs22 . 4\plain \f0\super\fs28 r\plain \f0\fs22 . 23\plain \f0\super\fs28 v\plain \f0\fs22 . 38\plain \f0\super\fs28 v\plain \f0\fs22 . 48\plain \f0\super\fs28 r\plain \f0\fs22 . 57\plain \f0\super\fs28 v\plain \f0\fs22 . 63\plain \f0\super\fs28 r\plain \f0\fs22 . 71\plain \f0\super\fs28 r\plain \f0\fs22 . 76\plain \f0\super\fs28 v\plain \f0\fs22 . 77\plain \f0\super\fs28 r\plain \f0\fs22 . 84\plain \f0\super\fs28 v\plain \f0\fs22 . 85\plain \f0\super\fs28 v\plain \f0\fs22 . 111\plain \f0\super\fs28 v\plain \f0\fs22 . 131\plain \f0\super\fs28 r\plain \f0\fs22 . 132\plain \f0\super\fs28 r\plain \f0\fs22 . 142\plain \f0\super\fs28 r\plain \f0\fs22 . 157\plain \f0\super\fs28 v\plain \f0\fs22 . 168\plain \f0\super\fs28 v\plain \f0\fs22 . 169\plain \f0\super\fs28 r\plain \f0\fs22 . 188\plain \f0\super\fs28 v\plain \f0\fs22 ; Werkstatt "Werden", E. 15. Jh., vgl. Hemfort, Monastische Buchkunst, 2001, S. 157, Abb. 206) \u183 \'b7 188\plain \f0\super\fs28 r\plain \f0\fs22  Besitzvermerk (?) (durch Palimpsestierung getilgt): \plain \f0\i\fs22 Aberden