\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 1\plain \f0\super\fs28 r\plain \f0\fs22 -12\plain \f0\super\fs28 v\plain \f0\fs22  [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Kalendarium}}\plain \f0\fs22 ], lat.-obd. (els\u228 \'e4ss.). Auf den Rektoseiten lat. Fest- und astronomischer Kalender (els\u228 \'e4ss. Monatsnamen erg\u228 \'e4nzt, vgl. Hans Jeske: Zu den deutschen Monatsnamen. In: Studia Neophilologica 55 (1983), S. 31-46, v.a. S. 42) mit Tagesangabe, Mondzyklen (beginnend mit den Jahren 1406, 1424, 1444 und 1463), Goldener Zahl, r\u246 \'f6mischer Kalenderz\u228 \'e4hlung, Heiligennamen (mit roten Eintr\u228 \'e4gen zum Tierkreis; aus verschiedenen Di\u246 \'f6zesan- und Ordenskalendern kumuliert: Stra\u223 \'dfburg: Athala (3. Dez.), Arbogast (21. Juli, rot); Bremen: Donatus mr. (12. Dez.), Eugenia (23. Dez.); Speyer: Sophia (10. Mai); Kopenhagen: Cyprianus (8. M\u228 \'e4rz); Brixen: Caelestinus (5. April); Trient: Hyrena (6. April); Amiens: Septem viduae (9. April); Cavaillon: Faustinus (20. Mai) u.a.; mehrfach Doppelbesetzungen und zahlreiche Fehler; zeitgleiche Nachtr\u228 \'e4ge und Erg\u228 \'e4nzungen unspezifischer als der Hauptbestand), Tagesl\u228 \'e4nge und Sonnenstand f\u252 \'fcr Stra\u223 \'dfburg sowie lat. Kalenderversen (1\plain \f0\super\fs28 r\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 In Jano claris calidisque cibis pociaris}}\plain \f0\i\fs22  / ... \plain \f0\fs22 Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Thorndike/Kibre, Catalogue of Incipits, 1963}}\plain \f0\fs22 , Sp. 683); auf den Versoseiten els\u228 \'e4ss. Aderla\u223 \'dfregeln in Verbindung mit Auslegung der Tierkreiszeichen (1\plain \f0\super\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Artistoteles der meister lert uns: In dem genner soltu nit la\u223 \'dfen}}\plain \f0\i\fs22  ... - ... und eben hellen und g\u367 uoter fride.\plain \f0\fs22  Zu Werk und \u220 \'dcberlieferung vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Zinner, Verzeichnis, 1925}}\plain \f0\fs22 , S. 446 (Nr. 5370)).}

