\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Koch, Karlssage, 2002}}\plain \f0\fs22 , passim (v.a. S. 28). - {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Saurma-Jeltsch, Sp\u228 \'e4tformen, 2001}}\plain \f0\fs22 , Bd. 1, Reg., s.v.; Bd. 2, S. 8f. (Nr. 7; Lit.). - {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Handschriftenzensus Rheinland}}\plain \f0\fs22 , Nr. 207. - {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kr\u228 \'e4mer, Handschriftenerbe, 1989-1990}}\plain \f0\fs22 , Bd. 1, S. 87. - {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Fligge, Best\u228 \'e4nde Duisburg}}\plain \f0\fs22 , S. 191 (Nr.\~12). - Becker, S. [434f.]. - {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lejeune/Stiennon, L\u233 \'e9gende de Roland, 1966}}\plain \f0\fs22 , v.a. Bd. 1, S. 240-243. - {\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Karl der Gro\u223 \'dfe, 1965}}\plain \f0\fs22 , S. 532 (Nr. 730). - {\field{\*\fldinst HYPERLINK "hida://bezlit[7].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Rheinische Handschriften Bonn}}\plain \f0\fs22 , S. 9; 13. - {\field{\*\fldinst HYPERLINK "hida://bezlit[8].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Drescher, Bonner Hs von Strickers Karl, 1906}}\plain \f0\fs22 , S. 367-369. - HSA, Bonn Universit\u228 \'e4tsbibliothek [Kasten 26], s.v. 'S 500'. - {\field{\*\fldinst HYPERLINK "hida://bezlit[9].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Klette/St\u228 \'e4nder}}\plain \f0\fs22 , Nr. 500.}

