\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 278\plain \f0\super\fs28 r\plain \f0\fs22 -288\plain \f0\super\fs28 r\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Littera studii Tolosani [de Scismate] ad regem Francorum}}\plain \f0\fs22 . Titel (Nachtrag von Kalteisen): \plain \f0\i\fs22 Littera studii Tolosani ad regem Francorum.\plain \f0\fs22  Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Orthodoxe et invictissime rex, pugil fidei, brachium inclitum, dextrum ecclesie}}\plain \f0\i\fs22  ... - ... vestra dyademate temporali deposita in inaccessibilem coronam glorie percipiendam finaliter sempiternam. Amen.\plain \f0\fs22  \plain \f0\i\fs22 >Eiusdem\plain \f0\fs22  (erg\u228 \'e4nzt \plain \f0\i\fs22 maiestatis\plain \f0\fs22 ) \plain \f0\i\fs22 regi filia humilima et devota universitas studii Tholosani<.\plain \f0\fs22  \u220 \'dcberlieferung auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Escorial, BReal, L. II. 17}}\plain \f0\fs22 , 125\plain \f0\super\fs28 r\plain \f0\fs22 -140\plain \f0\super\fs28 v\plain \f0\fs22 , vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Ant\u243 \'f3lin, El Escorial, 1910-1923}}\plain \f0\fs22 , Bd. 3, S. 21.\plain \f0\b\fs22  \plain \f0\fs22 Am Rand zahlreiche Glossen, Erg\u228 \'e4nzungen und Korrekturen von Schreiberhand, Kalteisen und weiterer Hand, 1. Dr. 15. Jh. 288\plain \f0\super\fs28 v\plain \f0\fs22  leer. Handwechsel.}

