\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 [TE]. - (III-1)\plain \f0\super\fs28 5\plain \f0\fs22  + (VI-2)\plain \f0\super\fs28 15\plain \f0\fs22  + (VI-3)\plain \f0\super\fs28 24\plain \f0\fs22  + VI\plain \f0\super\fs28 36\plain \f0\fs22  + (V-7)\plain \f0\super\fs28 39\plain \f0\fs22  + V\plain \f0\super\fs28 49\plain \f0\fs22  + II\plain \f0\super\fs28 53\plain \f0\fs22  + VI\plain \f0\super\fs28 65\plain \f0\fs22  + III\plain \f0\super\fs28 71\plain \f0\fs22  + 4 VI\plain \f0\super\fs28 119\plain \f0\fs22  + (III-1)\plain \f0\super\fs28 124\plain \f0\fs22  + IV\plain \f0\super\fs28 132\plain \f0\fs22  + II\plain \f0\super\fs28 136\plain \f0\fs22  + (VIII-2)\plain \f0\super\fs28 150\plain \f0\fs22  + V\plain \f0\super\fs28 160\plain \f0\fs22  + IV\plain \f0\super\fs28 168\plain \f0\fs22  + VI\plain \f0\super\fs28 180\plain \f0\fs22  + 2 IV\plain \f0\super\fs28 196\plain \f0\fs22  + V\plain \f0\super\fs28 206\plain \f0\fs22  + VII\plain \f0\super\fs28 220\plain \f0\fs22  + (VIII-7)\plain \f0\super\fs28 229\plain \f0\fs22  + (V-1)\plain \f0\super\fs28 238\plain \f0\fs22  + (IV-4)\plain \f0\super\fs28 242\plain \f0\fs22 . Bll 183-186 Schaltzettel.\plain \f0\b\fs22  \plain \f0\fs22 Vereinzelt Reklamanten (IV-V). 1\plain \f0\super\fs28 r\plain \f0\fs22 -145\plain \f0\super\fs28 r\plain \f0\fs22  Paginierung, 16. Jh. Bll 128-129 mit Falzspuren \u183 \'b7 Schriftraum 18-19 \u215 \'d7 12-13 und 18,5 \u215 \'d7 12,5 (Bll 183-186) \u183 \'b7 2 Sp. (nur 137\plain \f0\super\fs28 ra\plain \f0\fs22 -138\plain \f0\super\fs28 vb\plain \f0\fs22 ) \u183 \'b7 25-45 Z. \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Kursive}}\plain \f0\fs22 , {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Hybrida}}\plain \f0\fs22  und {\field{\*\fldinst HYPERLINK "hida://5704[2]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Gotico-Humanistica}}\plain \f0\fs22 , mehrere H\u228 \'e4nde (Henricus Kalteisen u.a.) \u183 \'b7 Vereinzelt Rubrizierung und einfache schwarze Lombarden \u183 \'b7 Mehrere {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Schemata}}\plain \f0\fs22  (13\plain \f0\super\fs28 v\plain \f0\fs22 -14\plain \f0\super\fs28 r\plain \f0\fs22 )}

