\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 193\plain \f0\super\fs28 v\plain \f0\fs22 -198\plain \f0\super\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Gebete an Christus}}\plain \f0\fs22 . Sammlung von zwei Gebeten: Nr. 1 (193\plain \f0\super\fs28 v\plain \f0\fs22 -196\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 O zoete unde gutertirne here Jesu Christe, untfenge nu myn dorre herte}}\plain \f0\i\fs22  ...\plain \f0\fs22 ;\plain \f0\i\fs22  \plain \f0\fs22 Nr. 2 (196\plain \f0\super\fs28 r\plain \f0\fs22 -198\plain \f0\super\fs28 v\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 O gutertirne mylde here Jesu Christe, ick rope nu to dij mytten rouwygen mordener}}\plain \f0\i\fs22  ... \plain \f0\fs22 Handwechsel.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

