\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 Nach Wz (Typus PiccOnline 21159: Stade 1659), rheinmaasl\u228 \'e4ndisch-brabantischer Schreibsprache, Heiligennamen der Litanei (s.u.) sowie partieller Hand\u252 \'fcberschneidung mit S 2059 (Geldern, um 1650) um 1650 im Umfeld des {\field{\*\fldinst HYPERLINK "hida://bezsoz[1].4600/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Augustiner-Chorfrauenklosters Nazareth in Geldern}}\plain \f0\fs22  entstanden. Nach Auf\-l\u246 \'f6sung des Klosters (1802) wie Bonn, ULB, S 2052, S 2054-2057 und S 2059 um 1820/45 in den Besitz des Kartographen, Lokalhistorikers und Kunst\-sammlers {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Michael Buyx}}\plain \f0\fs22  (1795-1882, vgl.\~Dassel/Kwiat\-kowski, Buyx, v.a. S.\~11\endash 14; 380\endash 383; Costard, Frauen\-fr\u246 \'f6m\-mig\-keit, S. 70f.) in Nieukerk (Kerken bei Geldern) gekommen. Als Buyx\rquote sches Familienerbe um 1909 in den Besitz von dessen Enkelin {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Maria M\u252 \'fcllenmeister}}\plain \f0\fs22  (\u8224 \'86 1963, vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Dassel/Kwiat\-\-\-\-kowski, Buyx}}\plain \f0\fs22 , S.\~382f.; Becker, Bonner Hss., S. [878]) und von dort 1933\plain \f1\lang1033\fs20  \plain \f0\fs22 in die Universit\u228 \'e4tsbibliothek Bonn gekommen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

