\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 196\plain \f2\super\lang1033\fs28 r\plain \f0\fs22 -231\plain \f2\super\lang1033\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Rosenkranz und Krone Mariae}}\plain \f0\fs22 , ndl. \plain \f2\i\lang1033\fs22 \u8250 \'9bHier begynt onser liever vrouwen roesen kranss. Pater noster\u8249 \'8b. Den du van den geist onfanges. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 O du werde moder ons lieven heren Jhesu Christi. Als du dit wort godz dese gruet van den engel Gabriel oitmoedelicken ontfynges ind by dy behieldes ind vrucht des ewigen levens daer van brechtes. O Maria, alsoe help my, dat ick dat woert gadz oetmoedilicken hoer ind by my behalde vruchtbairlicke. Amen. \u8250 \'9bAve Maria\u8249 \'8b}}\plain \f2\i\lang1033\fs22  ... \plain \f0\fs22 -\plain \f2\i\lang1033\fs22  ... doe bevele ic my ende aller myn lieve vrynde, dy in dyn huede sunderlingen bevele ick dy alle die tyt myns levens myn lyff, myn siele in den ynnersten gront dyns herten, dat sonder onderlait vlie\-ten\-de is van barmherticheit end der genaden gadz. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 232\plain \f2\super\lang1033\fs28 r\plain \f0\fs22 -273\plain \f2\super\lang1033\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Rosenkranz Mariae}}\plain \f0\fs22 , ndl. \plain \f2\i\lang1033\fs22 \u8250 \'9bHier begynt dat ierste krensken dat sal men lesen in die eer, dat die soen gadz ontfangen wart van Marien synre liever moder in oeren reynen iom\-fer\-licken licham. [Vor]leest eyn Pater noster. Ave\u8249 \'8b. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\i\lang1033\fs22\chcbpat17 Dye van den engel die boetschop ontfynges, dattu die moder godz soldes wesen. \u8250 \'9bAve\u8249 \'8b. Dye oetmoedelicken spracket (!): Siet hier, die derne des heren, my gesche na dynen worden}}\plain \f2\i\lang1033\fs22  ... \plain \f0\fs22 -\plain \f2\i\lang1033\fs22  ... ende byd dy oetmoedeliken, dat du barmhertich wesen wyls deser ser[...] \plain \f0\fs22 [unleserlich]\plain \f2\i\lang1033\fs22 , daer ic nun von gebeden heb en voer alle gelovige sielen, op dat wy ende sy mytty comen moeten in dat ewige leven, des wyl ons, lieve barmhertige here gonnen doer dynen onschuldigen doet. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

